[HttpGet("{id}")]
public async Task<ActionResult<ProductDto>> Get(int id)
{
    // Set a breakpoint here to inspect:
    // 1. The 'id' parameter value from the route
    // 2. ModelState.IsValid (should be true for simple types)
    // 3. HttpContext.Request.Path and QueryString

    var product = await _service.GetByIdAsync(id);
    // Inspect 'product' here to see what the service returned

    if (product is null)
    {
        // Breakpoint here confirms the service returned null
        return NotFound();
    }

    return Ok(product);
    // Inspect the serialized response in the debugger
}

